package com.taskflow.userservice.service; import com.taskflow.userservice.dto.*; import com.taskflow.userservice.entity.User; import com.taskflow.userservice.exception.*; import com.taskflow.userservice.repository.UserRepository; import java.util.*; import org.slf4j.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @Transactional public class UserServiceImpl implements UserService { private static final Logger log=LoggerFactory.getLogger(UserServiceImpl.class); private final UserRepository repo; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); public UserServiceImpl(UserRepository r){repo=r;} private UserResponse view(User u){return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getCreatedAt(),u.getUpdatedAt());} public UserResponse register(UserRegistrationRequest r){if(repo.existsByEmail(r.email().toLowerCase()))throw new DuplicateEmailException("Email is already registered");User u=new User();u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));log.info("Registering user with email {}",u.getEmail());return view(repo.save(u));} public UserResponse authenticate(String email,String password){String normalized=email.trim().toLowerCase();User u=repo.findByEmailIgnoreCase(normalized).orElse(null);if(u==null||!encoder.matches(password,u.getPassword())){log.warn("Login failed for email {}",normalized);throw new org.springframework.security.authentication.BadCredentialsException("Invalid email or password");}log.info("Login succeeded for user {}",u.getId());return view(u);} @Transactional(readOnly=true) public UserResponse getById(Long id){return repo.findById(id).map(this::view).orElseThrow(()->new ResourceNotFoundException("User not found: "+id));} @Transactional(readOnly=true) public List<UserResponse> getAll(){return repo.findAll().stream().map(this::view).toList();} public UserResponse update(Long id,UserUpdateRequest r){User u=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found: "+id));String email=r.email().toLowerCase();if(!u.getEmail().equals(email)&&repo.existsByEmail(email))throw new DuplicateEmailException("Email is already registered");u.setName(r.name());u.setEmail(email);return view(repo.save(u));} public void delete(Long id){if(!repo.existsById(id))throw new ResourceNotFoundException("User not found: "+id);repo.deleteById(id);} @Transactional(readOnly=true) public boolean emailExists(String email){return repo.existsByEmail(email.toLowerCase());} }
